import os,json,subprocess,shutil,hashlib
from pathlib import Path
out={"pm2":{},"units":{},"code":{},"processes":{},"os_prerequisites":{}}
for n in ("pm2","node","bash","systemctl"):
 out["os_prerequisites"][n]=shutil.which(n)
try:
 r=subprocess.run(["pm2","-v"],capture_output=True,text=True,timeout=6)
 out["pm2"]["version"]=r.stdout.strip()[:30]
except Exception:pass
p=Path("/etc/systemd/system/pm2-root.service")
if p.is_file():
 lines=p.read_text(errors="replace").splitlines()
 out["units"]["global"]=[v for v in lines if v.startswith(("User=","Environment=","ExecStart=","ExecStop=","ExecReload=","PIDFile=","Type=","RemainAfterExit="))]
for n in ("telegram-robot-leads","iptvpn-bot"):
 p=Path("/srv/projects")/n
 out["code"][n]={}
 for rel in ("ecosystem.config.js","main.py","start.sh"):
  f=p/rel
  if f.is_file():out["code"][n][rel]={"sha256":hashlib.sha256(f.read_bytes()).hexdigest(),"uid":f.stat().st_uid,"mode":oct(f.stat().st_mode&0o777)}
 out["code"][n][".pm2_home_missing"]=not (p/".pm2").exists()
 out["code"][n]["uid"]=p.stat().st_uid
 out["code"][n]["gid"]=p.stat().st_gid
 out["code"][n]["lock_tmp_legacy"]=Path("/tmp/iptvpn_bot.lock").exists() if n=="iptvpn-bot" else None
try:
 proc=subprocess.run(["pm2","jlist"],capture_output=True,text=True,timeout=12,env=dict(os.environ,PM2_HOME="/root/.pm2"))
 if proc.returncode==0:
  for app in json.loads(proc.stdout):
   e=app.get("pm2_env") or {}
   out["processes"][app.get("name")]={"pid":app.get("pid"),"status":e.get("status"),"interpreter":e.get("exec_interpreter"),"script":e.get("pm_exec_path"),"cwd":e.get("pm_cwd"),"uid":e.get("uid"),"gid":e.get("gid"),"pm_out_log_path":e.get("pm_out_log_path"),"pm_err_log_path":e.get("pm_err_log_path"),"autorestart":e.get("autorestart"),"exec_mode":e.get("exec_mode"),"instances":e.get("instances"),"args_len":len(e.get("args") or []),"ecosystem_safe_env_names":sorted(k for k in (e.get("env") or {}) if k.startswith(("TELEGRAM_","IPTVPN_","PM2_")))}
except Exception as x:out["pm2"]["jlist_error"]=type(x).__name__
print(json.dumps(out,sort_keys=True,ensure_ascii=True))
